# --- 3. Visualisation des résultats ---

def plot_map(ax, polys, line, title):
    # Dessiner la route
    x_l, y_l = line.xy
    ax.plot(x_l, y_l, color='gray', linewidth=15, label='Road (Fixed)')
        
    # Dessiner les bâtiments
    for i, poly in enumerate(polys):
        x, y = poly.exterior.xy
        ax.fill(x, y, alpha=0.5, label=f'Building {i+1}')
        
    ax.set_title(title)
    ax.set_aspect('equal')
    ax.legend(loc='upper right', fontsize='small')

fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(15, 7))

plot_map(ax1, buildings, road, "Before Optimisation (Conflicts)")
plot_map(ax2, gen_gdf['geometry'], road, "After Simulated Annealing (Displacement)")

plt.tight_layout()
plt.show()